// Arabic phrase dictionary — keyed by the ENGLISH SOURCE TEXT.
//
// This is the bulk of the app's localization. A component writes:
//
//     <h2>{t('Cars here now')}</h2>
//
// …keeping the English exactly where it always was, and this file supplies the
// Arabic. There are no invented key names to maintain, and one entry covers
// every file that uses that sentence (25 screens share "Cancel").
//
// RULES
//   • The key must match the English in the source EXACTLY — same wording,
//     punctuation, capitalisation and apostrophe character (’ vs ').
//   • A missing entry is safe: t() returns the key, which is the English. The UI
//     degrades to English, never to a blank or a raw key path.
//   • {var} placeholders must survive translation, and may move within the
//     sentence — Arabic clause order differs from English.
//   • English needs no file here; it is the key.
//
// For strings that need PLURAL forms or different wording in different contexts,
// use a namespaced key in labels.js instead — see the header of that file.
//
// Keep sorted alphabetically by English key so merges stay reviewable.

