  'Admin-only demo console (only shown in Demo Mode): force a real "Service Due" oil alert or a fault-discovery ticket on a real car, watch the system react end-to-end, then roll it all back with one click.': 'وحدة عرض توضيحي للمسؤولين فقط (تظهر في وضع العرض التوضيحي فقط): أطلق تنبيه زيت حقيقيًا من نوع "صيانة مستحقة" أو تذكرة اكتشاف عطل على مركبة حقيقية، وراقب تفاعل النظام من البداية إلى النهاية، ثم تراجع عن كل شيء بضغطة واحدة.',
