  'Cars moved on with all faults fixed — each transfer noted and logged.': 'مركبات نُقلت بعد إصلاح جميع أعطالها — كل عملية نقل موثّقة ومسجّلة.',
  'Cars moved to a different garage even though every fault on the ticket was already fixed. Each move required a justification note — reviewed here so an unnecessary or mistaken transfer is caught.': 'مركبات نُقلت إلى كراج آخر رغم إصلاح جميع الأعطال المدرجة في التذكرة. كل عملية نقل تتطلب ملاحظة تبرير — تُراجَع هنا لاكتشاف أي نقل غير ضروري أو خاطئ.',
  'cars need a mileage review': 'مركبة تحتاج إلى مراجعة المسافة',
  'Cars Needing a Check': 'مركبات تحتاج إلى فحص',
  'Cars out on paid rental': 'المركبات المؤجَّرة بعقود مدفوعة',
  'Cars out on rental whose oil limit is coming up. Get the real odometer from the customer — the question is whether the car can finish the rental inside its allowance, not whether it has passed the limit.': 'المركبات المؤجَّرة التي يقترب فيها حد الزيت. احصل على قراءة العدّاد الحقيقية من العميل — فالسؤال هو ما إذا كانت المركبة تستطيع إنهاء الإيجار ضمن الحد المسموح، لا ما إذا كانت قد تجاوزت الحد.',
  'Cars sent back for a second look most often': 'المركبات الأكثر إعادةً لفحص ثانٍ',
  'Cars sitting in each garage right now': 'المركبات الموجودة حالياً في كل كراج',
  'Cars that came back for the SAME fault 3+ times — chronic problems worth investigating.': 'مركبات عادت بالعطل نفسه 3 مرات أو أكثر — مشكلات مزمنة تستحق التحقيق.',
  'Cars that came back with the SAME confirmed fault after a completed repair. Each case shows the previous ticket, garage, parts used, days and distance since the repair, and how many times it recurred — so management can decide whether the earlier repair failed, it is a new failure, workshop responsibility, customer misuse, or needs investigation.': 'مركبات عادت بالعطل المؤكَّد نفسه بعد إصلاح مكتمل. تعرض كل حالة التذكرة السابقة والكراج وقطع الغيار المستخدمة وعدد الأيام والمسافة منذ الإصلاح وعدد مرات التكرار — لتقرر الإدارة ما إذا كان الإصلاح السابق قد فشل، أم أنه عطل جديد، أم مسؤولية الورشة، أم سوء استخدام من العميل، أم يحتاج إلى تحقيق.',
  'Cars that have physically left the garage but still owe an invoice. Chase the garage, then request / record the invoice on the ticket.': 'مركبات غادرت الكراج فعلياً لكن فاتورتها لم تصل بعد. تابع الكراج ثم اطلب الفاتورة أو سجّلها في التذكرة.',
  'Cars that have stalled at the garage': 'مركبات متوقفة بلا تقدّم في الكراج',
  'Cars that keep coming back': 'مركبات تتكرر عودتها',
  'Cars that left the garage while their maintenance contract stayed open.': 'مركبات غادرت الكراج بينما بقي عقد الصيانة الخاص بها مفتوحاً.',
  'Cars that left the garage with no invoice entered — chase the bill': 'سيارات غادرت الكراج دون إدخال فاتورة — تابع تحصيل الفاتورة',
  'Cars that received the SAME part twice within the selected window. Each row shows both purchases, how far apart they were, what each cost, and who approved them. Matching is by part name — part numbers are hand-typed and differ between suppliers for the same component, so a number-only match would report a clean fleet while the same part goes on twice.': 'المركبات التي رُكِّبت عليها القطعة نفسها مرتين خلال الفترة المحددة. يعرض كل سطر عمليتي الشراء، والمدة الفاصلة بينهما، وتكلفة كل منهما، ومن اعتمدهما. تتم المطابقة باسم القطعة — فأرقام القطع تُدخَل يدويًا وتختلف بين المورّدين للقطعة الواحدة، ولذلك فإن المطابقة بالرقم وحده ستُظهر أسطولًا سليمًا بينما تُركَّب القطعة نفسها مرتين.',
  'Cars that returned with the SAME confirmed fault after a completed repair. Review the evidence and decide why it came back.': 'مركبات عادت بالعطل المؤكَّد نفسه بعد إصلاح مكتمل. راجع الأدلة وحدّد سبب عودتها.',
  'Cars that spent the most days off the road': 'المركبات التي قضت أكبر عدد من الأيام خارج الخدمة',
  'Cars that went back to the workshop most often': 'المركبات الأكثر تكراراً في العودة إلى الورشة',
  'Cars transferred on most often': 'المركبات الأكثر نقلاً بين الكراجات',
  'Cars Waiting for Follow-up': 'مركبات بانتظار المتابعة',
