  'e.g. typo — extra digit at handover': 'مثال: خطأ إدخال — رقم زائد عند التسليم',
  'Each board is the full row set behind the card above it — open any number and audit it.': 'كل لوحة تعرض جميع السجلات التي تقف خلف البطاقة أعلاها — افتح أي رقم لتدقيقه.',
  'Each car': 'كل مركبة',
  "Each car's odometer as it was captured at every workflow stage — inspection test drive, breakdown report, pickup intake, dispatch to garage, at garage, garage return and re-inspection. A red step ran backwards versus the stage before it.": 'عداد كل مركبة كما سُجّل في كل مرحلة من مراحل سير العمل — قيادة اختبار الفحص، بلاغ العطل، استلام المركبة، الإرسال إلى الكراج، داخل الكراج، العودة من الكراج وإعادة الفحص. الخطوة الحمراء تعني قراءة أقل من المرحلة التي سبقتها.',
