  'Estimated — each visit\'s cost is attributed to its dominant fault category, not a booked per-line split.': 'تقديري — تُنسب تكلفة كل زيارة إلى فئة العطل الغالبة فيها، وليست توزيعًا محاسبيًا لكل بند.',
