  "Files a real customer complaint against the target car. Watch the ticket appear in the Inspector's Pad and the Maintenance Workflow board, ready for a supervisor to dispatch.": 'يسجّل شكوى عميل حقيقية على المركبة المستهدفة. راقب ظهور التذكرة في لوحة الفاحص وفي لوحة سير عمل الصيانة، جاهزة ليوجّهها المشرف إلى كراج.',
  'Fill in the sections below — auto-filled values stay editable.': 'املأ الأقسام أدناه — القيم المعبّأة تلقائياً تبقى قابلة للتعديل.',
