  'Flags the car as physically back at base. The return handover (odometer, fuel, condition, signature) is still owed before the repair can resume.': 'يسجّل أن المركبة عادت فعليًا إلى المقر. لا يزال تسليم العودة (العدّاد، الوقود، الحالة، التوقيع) مطلوبًا قبل استئناف الإصلاح.',
