  'Fleet drivers with their licence number, expiry and status. Add, edit or suspend drivers; expiring licences are flagged.': 'سائقو الأسطول مع أرقام رخصهم وتواريخ انتهائها وحالتها. أضف سائقين أو عدّلهم أو أوقفهم؛ الرخص المقاربة على الانتهاء مُعلَّمة.',
