  'Fleet maintenance spend divided by total validated distance. Computed on totals, not an average of per-car ratios.': 'إجمالي إنفاق صيانة الأسطول مقسومًا على إجمالي المسافة المُتحقَّق منها. يُحتسب على الإجماليات، لا كمتوسط لنسب المركبات الفردية.',
