  'Fleet status at a glance, then the cars that need attention first — undocumented handovers over 24h and cars missing a data entry. The full lists stay collapsed until you ask for them.': 'حالة الأسطول في لمحة، ثم المركبات التي تحتاج انتباهًا أولًا — عمليات التسليم غير الموثّقة منذ أكثر من 24 ساعة، والمركبات التي تنقصها بيانات. تبقى القوائم الكاملة مطوية حتى تطلبها.',
  'Fleet Utilization': 'استغلال الأسطول',
  'Fleet-wide': 'على مستوى الأسطول',
  'Fleet-wide distance driven with no contract to explain it — the reconciliation gap. Individual cars can be far larger than this net figure.': 'المسافة المقطوعة على مستوى الأسطول دون عقد يفسّرها — فجوة التسوية. قد تكون الفجوة في مركبات بعينها أكبر بكثير من هذا الرقم الصافي.',
  'Fleet-wide logged maintenance spend. Cars without a reliable odometer reading are excluded from the per-km figure.': 'إجمالي إنفاق الصيانة المسجَّل على مستوى الأسطول. تُستثنى المركبات التي لا تملك قراءة عدّاد موثوقة من حساب التكلفة لكل كم.',
  'Fleet-wide overview: how many cars are available, rented, or in maintenance, plus key totals. Availability and composition come from the OfficeManager lifecycle status.': 'نظرة عامة على الأسطول: كم مركبة متاحة أو مؤجَّرة أو في الصيانة، إضافة إلى الإجماليات الرئيسية. التوافر والتركيبة مستمدان من حالة دورة الحياة في OfficeManager.',
