  'It cannot be rented or booked without a manager’s override. Send it to the garage, or pick another car.': 'لا يمكن تأجيرها أو حجزها دون تجاوز من المدير. أرسلها إلى الكراج أو اختر مركبة أخرى.',
  'It cannot be rented or booked. Pick another car, or send this one to maintenance first.': 'لا يمكن تأجيرها أو حجزها. اختر مركبة أخرى أو أرسل هذه إلى الصيانة أولاً.',
  'It was interrupted or a phase failed before the change feed was recorded — so there is nothing to show. Re-run the sync and let it finish: the “Checking for recently-returned contracts…” step queries the OM API and can take a minute, so don’t close the window until you see “Sync done.”': 'جرى إيقافها أو فشلت إحدى المراحل قبل تسجيل سجل التغييرات، لذلك لا يوجد ما يُعرض. أعد تشغيل المزامنة ودعها تكتمل حتى النهاية: خطوة «Checking for recently-returned contracts…» تستعلم من واجهة OM وقد تستغرق دقيقة، فلا تُغلق النافذة حتى تظهر لك «Sync done.»',
  'It won\'t apply immediately — it will be sent to an admin for approval, along with the note below.': 'لن يُطبَّق فوراً — سيُرسل إلى المسؤول للموافقة، مرفقاً بالملاحظة أدناه.',
  'It won’t apply immediately — it will be sent to an admin for approval, along with the note below.': 'لن يُطبَّق فوراً — بل سيُرسل إلى مسؤول للموافقة عليه، مرفقاً بالملاحظة أدناه.',
  'Itemise the bill so cost is tracked per part and per repair. Totals add up automatically.': 'فصّل الفاتورة بنوداً ليُتابع التكلفة لكل قطعة غيار ولكل إصلاح. تُجمع الإجماليات تلقائياً.',
