  'Live condition checks — resolvable blockers are enforced again when you confirm the rental.': 'فحوص حالة مباشرة — تُطبَّق الموانع القابلة للحل مرة أخرى عند تأكيد الإيجار.',
  'Live data · simulated actions': 'بيانات مباشرة · إجراءات محاكاة',
  'Live fleet alerts — overdue rentals, maintenance overruns, expiring documents, service-due cars and approvals. The bell in the top bar updates in real time.': 'تنبيهات الأسطول المباشرة — إيجارات متأخرة، وتجاوزات في الصيانة، ومستندات قاربت على الانتهاء، وسيارات مستحقة للخدمة، وموافقات. يتحدّث الجرس في الشريط العلوي لحظياً.',
  'Live fleet alerts, organised into role-aware action lanes.': 'تنبيهات الأسطول المباشرة، منظّمة في مسارات إجراءات حسب الدور.',
  'Live now': 'مباشر الآن',
  'Live snapshot of your fleet’s status and operations.': 'لقطة حيّة لحالة أسطولك وعملياته.',
  'Live stage board — every car by the exact workflow stage it sits in and who is responsible right now.': 'لوحة مراحل حيّة — كل سيارة حسب مرحلة سير العمل التي تقف عندها بالضبط ومن المسؤول عنها الآن.',
  'Live summary of this {phase} inspection — export a standalone, photo-embedded report.': 'ملخّص مباشر لفحص {phase} — صدّر تقريرًا مستقلًا بذاته تُضمَّن فيه الصور.',
  'Live triage of the fleet in three columns — Action Required / In Workshop / Available Pool — with a Swap & Renew engine that keeps a customer on the road while their car is repaired.': 'فرز حيّ للأسطول في ثلاثة أعمدة — يتطلب إجراء / في الورشة / المتاح — مع محرّك الاستبدال والتجديد الذي يُبقي العميل على الطريق أثناء إصلاح سيارته.',
  'Live triage of the fleet: what needs maintenance, what': 'فرز حيّ للأسطول: ما الذي يحتاج صيانة، وما الذي',
  "Live triage of the fleet: what needs maintenance, what's in the workshop, and what's ready to deploy. The Swap & Renew engine keeps a customer on the road while their car gets fixed.": 'فرز مباشر للأسطول: ما يحتاج إلى صيانة، وما هو داخل الورشة، وما هو جاهز للتشغيل. محرّك التبديل والتجديد يبقي العميل على الطريق بينما تُصلَح مركبته.',
