  'Maintenance = true off-road shop days — workshop days with no active rental, from the OfficeManager maintenance contracts. Rental is King: a day a car is both on rent and in the shop counts as': 'الصيانة = أيام الورشة الفعلية خارج الطريق — أيام الورشة بلا إيجار نشط، من عقود الصيانة في OfficeManager. الإيجار له الأولوية: اليوم الذي تكون فيه السيارة مؤجَّرة وفي الورشة معًا يُحتسب',
  'Maintenance = true off-road shop days — workshop days with no active rental, from the OfficeManager maintenance contracts. Rental is King: a day a car is both on rent and in the shop counts as rental time, never shop time. The three always add up to days in service.': 'الصيانة = أيام التوقف الفعلية خارج الخدمة — أي أيام الورشة التي لا يوجد فيها إيجار نشط، مأخوذة من عقود الصيانة في OfficeManager. الإيجار هو الأصل: اليوم الذي تكون فيه المركبة مؤجَّرة وفي الورشة معًا يُحتسب وقت إيجار لا وقت ورشة. والثلاثة مجتمعة تساوي دائمًا أيام الخدمة.',
