  'Maintenance cost ÷ in-service days. Lifetime-only — shows "—" while a date filter is active.': 'تكلفة الصيانة ÷ أيام الخدمة. تُحتسب لكامل العمر فقط — وتظهر "—" أثناء تفعيل فلتر التاريخ.',
  'Maintenance cost ÷ number of rentals.': 'تكلفة الصيانة ÷ عدد عمليات الإيجار.',
  'Maintenance cost ÷ validated distance. Lifetime-only — shows "—" while a date filter is active.': 'تكلفة الصيانة ÷ المسافة المتحقَّق منها. تُحتسب لكامل العمر فقط — وتظهر "—" أثناء تفعيل فلتر التاريخ.',
  'Maintenance cost per kilometre, per day and per rental for every car — the true running cost of each asset. Numerator is the same logged repair spend as the Profit Bridge; denominators are validated distance, in-service days and rental count. Cars with no measured distance show “—”, never a misleading zero.': 'تكلفة الصيانة لكل كيلومتر ولكل يوم ولكل عملية إيجار لكل سيارة — التكلفة التشغيلية الحقيقية لكل أصل. البسط هو نفس إنفاق الإصلاح المسجّل في جسر الأرباح؛ والمقامات هي المسافة المتحقَّق منها وأيام الخدمة وعدد عمليات الإيجار. السيارات بلا مسافة مقاسة تظهر “—” بدلًا من صفر مضلِّل.',
