  'Oil service recorded at {km} km — {ahead} km ahead of the last known reading, further than this car could have driven. Verify the sheet row before relying on the oil limit.': 'سُجّلت خدمة زيت عند {km} كم — أي بزيادة {ahead} كم عن آخر قراءة معروفة، وهي مسافة أكبر مما كان يمكن لهذه المركبة قطعه. تحقّق من سطر الجدول قبل الاعتماد على حد الزيت.',
  'Oil service recorded at {km} km, after the last known reading ({anchor} km) — a mid-rental service, not an error. The sheet carries no service date, so the estimate still runs from the last dated reading.': 'سُجّلت خدمة زيت عند {km} كم، أي بعد آخر قراءة معروفة ({anchor} كم) — وهي خدمة أثناء الإيجار وليست خطأ. ولا يحمل الجدول تاريخ الخدمة، لذا يظل التقدير محسوبًا من آخر قراءة مؤرّخة.',
