  'Once a ticket moves through the board, its stage-by-stage journey shows up here.': 'بمجرد أن تتحرّك التذكرة عبر اللوحة، يظهر مسارها مرحلةً بمرحلة هنا.',
  'Once tickets capture odometer readings through the maintenance workflow, each car': 'بمجرد أن تلتقط التذاكر قراءات العدّاد عبر سير عمل الصيانة، فإن كل مركبة',
  "Once tickets capture odometer readings through the maintenance workflow, each car's per-stage trail appears here.": 'بمجرد أن تسجّل التذاكر قراءات العداد عبر سير عمل الصيانة، يظهر هنا مسار كل مركبة حسب المرحلة.',
  'One garage': 'أحد الكراجات',
  'One home for every odometer/fuel tool, in three tabs: Fuel & Mileage (real travel vs. contract km, off-contract leakage, fuel debits), Reconciliation (stored odometer vs. the scanner baseline, adopt with one click) and Chain Audit (contract-to-contract odometer handoffs with a non-destructive Quick Fix).': 'مكان واحد يجمع كل أدوات العدّاد والوقود في ثلاث تبويبات: الوقود والمسافة (المسافة الفعلية مقابل كيلومترات العقود، والتسرّب خارج العقد، وخصومات الوقود)، والتسوية (العدّاد المخزَّن مقابل خط الأساس المُعاد بناؤه، مع الاعتماد بنقرة واحدة)، وتدقيق السلسلة (تسليم العدّاد من عقد إلى عقد مع إصلاح سريع غير مُتلِف).',
  'one unified read over three append-only trails — the vehicle event log (workflow, readiness, condition, cleaning), the logistics movement log, and inspection records. Every row carries who acted and when; nothing here can be edited.': 'قراءة موحّدة من ثلاثة سجلات لا تقبل إلا الإضافة — سجل أحداث المركبة (سير العمل، الجاهزية، الحالة، النظافة)، وسجل حركات النقل، وسجلات الفحص. كل سطر يحمل اسم من نفّذ الإجراء ووقته؛ ولا شيء هنا قابل للتعديل.',
  'Online': 'متصل',
