  "Only charges that still carry a balance are shown; fully-settled and reversed “wash” entries (a charge raised then credited back, e.g. an accident breach) are excluded so the total is exactly what's collectable — OfficeManager's Balance ({amount}).": 'تُعرض فقط الرسوم التي ما زال عليها رصيد؛ وتُستبعَد القيود المُسوَّاة بالكامل والمعكوسة (رسم حُمِّل ثم أُعيد قيده، مثل مخالفة حادث) ليكون الإجمالي هو المبلغ القابل للتحصيل تمامًا — رصيد OfficeManager ({amount}).',
