  'Out-of-contract km = Actual − On-contract. Kilometres the car moved with NO contract to explain them — office runs, transport, unlogged use. Big gaps get flagged.': 'الكيلومترات خارج العقد = الفعلية − التي يغطيها العقد. أي المسافة التي قطعتها المركبة دون عقد يفسّرها — مشاوير المكتب، النقل، الاستخدام غير المسجَّل. تُؤشَّر الفجوات الكبيرة.',
