  'Outstanding = Charged − Settled, per category — this is OfficeManager\'s own ledger and totals exactly to the': 'المستحق = المُحتسب − المُسدَّد، لكل فئة — هذا هو سجل OfficeManager نفسه ويطابق إجماليه تمامًا',
  "Outstanding = Charged − Settled, per category — this is OfficeManager's own ledger and totals exactly to the Balance ({amount}). The highlighted row is the charge that's still owed.": 'المستحق = المُحمَّل − المُسدَّد لكل فئة — هذا سجل OfficeManager نفسه، وإجماليه يطابق الرصيد ({amount}) تمامًا. الصف المميَّز هو الرسم الذي ما زال مستحقًا.',
  "Outstanding = Charged − Settled, per category, summed across every contract — this is OfficeManager's ledger and totals exactly to the customer's {term} ({amount}). Red rows are still owed; green rows are in the customer's favour (e.g. discounts).": 'المستحق = المُحتسب − المُسدَّد، لكل فئة، مجموعًا عبر كل العقود — هذا هو دفتر OfficeManager ويطابق تمامًا {term} العميل ({amount}). الصفوف الحمراء ما زالت مستحقة، والصفوف الخضراء لصالح العميل (مثل الخصومات).',
