  'Per car, for the chosen period: real odometer travel vs. the kilometres your contracts explain — the gap is distance driven off-contract. Plus fuel debited back for under-fuelled returns. Click any car for its trip-by-trip ledger.': 'لكل مركبة، خلال الفترة المختارة: المسافة الفعلية على العدّاد مقابل الكيلومترات التي تفسّرها العقود — والفارق هو مسافة قُطعت خارج العقود. إضافةً إلى الوقود المُحمَّل على العميل عند الإرجاع بوقود ناقص. اضغط على أي مركبة لعرض سجلها رحلةً برحلة.',
