  'Per-car km service interval from the Oil Change sheet (Validity).': 'فترة الخدمة بالكيلومترات لكل سيارة من جدول تغيير الزيت (Validity).',
  'Per-car split of owned time into rented, in-maintenance and idle days.': 'توزيع مدة التملّك لكل سيارة إلى أيام مؤجَّرة وأيام في الصيانة وأيام خاملة.',
  'Per-car split of owned time into rented, in-maintenance, and idle days — utilization and downtime % against how long you have owned each car, with rent lost to downtime.': 'توزيع مدة التملّك لكل سيارة إلى أيام مؤجَّرة وأيام في الصيانة وأيام خاملة — نسبة الاستغلال والتعطّل مقابل مدة تملّك كل سيارة، مع الإيجار المفقود بسبب التعطّل.',
  'Per-car split of owned time into rented, in-maintenance, and idle days — utilization and downtime % against how long you have owned each car, with rent lost to downtime. Filter by period (e.g. last month) and sort to find the cars stuck in the workshop.': 'توزيع مدة التملّك لكل سيارة إلى أيام مؤجَّرة وأيام في الصيانة وأيام خاملة — نسبة الاستغلال والتعطّل مقابل مدة تملّك كل سيارة، مع الإيجار المفقود بسبب التعطّل. صفِّ حسب الفترة (مثلًا الشهر الماضي) ورتِّب لتحديد السيارات العالقة في الورشة.',
  'Per-contract Net = Rent − Discount + Usage − Operating. These sum to Gross Revenue − Operating above; subtract car-level Maintenance to reach Lifetime Net Profit.': 'صافي العقد = الإيجار − الخصم + الاستخدام − التشغيل. ومجموع هذه البنود يساوي إجمالي الإيراد − التشغيل أعلاه؛ اطرح صيانة السيارة للوصول إلى صافي الربح لمدى الحياة.',
