  'Pick a car and a day to see what it was doing then — or add a “to” date to count how many days it was rented, in the workshop, or available.': 'اختر سيارة ويومًا لمعرفة وضعها حينها — أو أضف تاريخ «إلى» لحساب عدد الأيام التي كانت فيها مؤجَّرة أو في الورشة أو متاحة.',
  'Pick a car and the faults it has, and get the same fault-by-fault garage report the assign step shows — before any ticket exists.': 'اختر سيارة والأعطال الموجودة بها، واحصل على نفس تقرير الكراجات عطلًا بعطل الذي تعرضه خطوة الإسناد — قبل وجود أي تذكرة.',
  'Pick a car and the faults it has, and get the same fault-by-fault garage report the assign step shows — before any ticket exists. Each fault names its strongest garage, the best alternative, and the trade-off between them, with the repair history behind every figure. Read-only: it answers the question, it does not dispatch the car.': 'اختر سيارة والأعطال الموجودة بها، واحصل على نفس تقرير الكراجات عطلًا بعطل الذي تعرضه خطوة الإسناد — قبل وجود أي تذكرة. يحدد كل عطل أقوى كراج له، وأفضل بديل، والمفاضلة بينهما، مع سجل الإصلاح وراء كل رقم. للاطلاع فقط: يجيب على السؤال ولا يرسل السيارة.',
  'Pick a cause': 'اختر سببًا',
