  'Pick a type, or this part will be billed but won’t appear on the vehicle’s Installed Components tab.': 'اختر نوعًا، وإلا ستُحتسب هذه القطعة ماليًا دون أن تظهر في تبويب المكوّنات المركَّبة للمركبة.',
