  'Raise an inspection request now — sends it to the inspection-review queue. Leave off to just record the note.': 'أنشئ طلب فحص الآن — يُرسَل إلى قائمة مراجعة الفحوصات. اتركه مغلقًا لتسجيل الملاحظة فقط.',
